#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# ──────────────────────────────────────────────────────────────────────────
# STAGES: production 開通（#97，ADR 0008）。
#
#   bash scripts/production-wizard.sh      （Windows 用 Git Bash；需要 curl、node、gh，以及 npm ci 裝好的套件）
#
# live 的 key 只放在 Cloudflare 的 Worker secrets：輸入後直接 pipe 給 `wrangler secret put`，不寫檔、不印出來。
# ENV_FILE 只存不是秘密的 ID（Cloudflare account、D1、Paddle 的 product／price／webhook、client-side token），
# 重跑時用來跳過做過的步驟。GitHub 拿到 CLOUDFLARE_API_TOKEN（secret）與 CLOUDFLARE_ACCOUNT_ID、PADDLE_CLIENT_TOKEN、
# DEPLOY_ENABLED（variables），名字對應 .github/workflows/ci.yml。
#
# 隨時可以 Ctrl-C，之後重跑：已經設好的 secret 會問要不要換。Resend 的網域驗證與 Paddle 的網站審核要等，
# 還沒好之前 wizard 會停在那一步，好了再重跑。
# ──────────────────────────────────────────────────────────────────────────

ENV_FILE="$HOME/.config/naruhodo/production.env"
mkdir -p "$(dirname "$ENV_FILE")"

DOMAIN='naruhodo.page'
API_ORIGIN="https://api.$DOMAIN"
SITE_ORIGIN="https://$DOMAIN"
MAIL_DOMAIN="mail.$DOMAIN"
WORKER_CONFIG='worker/wrangler.jsonc'
SITE_CONFIG='site/wrangler.jsonc'
D1_NAME='naruhodo'
PADDLE_API_BASE_URL='https://api.paddle.com'
PADDLE_DASHBOARD='https://vendors.paddle.com'
# Worker 需要的 API key 權限；第 10 步照這份清單請使用者勾選，再用 GET / 核對。
PADDLE_PERMISSIONS=(transaction.write product.write price.write customer.write subscription.write
  notification_setting.write notification.read customer_portal_session.write)
WEBHOOK_EVENTS='["subscription.created","subscription.updated","subscription.activated","subscription.canceled","subscription.past_due","subscription.paused","subscription.resumed","transaction.completed","adjustment.updated"]'

CF_SECRETS=() # 這次設定到 Cloudflare 的 Worker secrets

wrangler() { npx --no-install wrangler "$@"; }

# json_get EXPR: 從 RESPONSE 取欄位，例如 json_get 'data.id'；取不到就是空字串。
json_get() {
  printf '%s' "$RESPONSE" | node -e '
    let s = ""; process.stdin.on("data", d => s += d).on("end", () => {
      let v; try { v = new Function("o", "return o." + process.argv[1])(JSON.parse(s)); } catch { v = undefined; }
      process.stdout.write(v == null ? "" : String(v));
    });' "$1"
}

# d1_id：Cloudflare 上名為 D1_NAME 的資料庫 id；還沒建立就是空字串。
d1_id() {
  wrangler d1 list --json 2>/dev/null | node -e '
    let s = ""; process.stdin.on("data", d => s += d).on("end", () => {
      try { const db = JSON.parse(s).find(x => x.name === process.argv[1]); process.stdout.write(db ? db.uuid : ""); } catch {}
    });' "$D1_NAME"
}

# api METHOD URL HEADERS [JSON]: 呼叫外部 API，設定 HTTP_STATUS 與 RESPONSE。HEADERS 可以有多行。
# 認證標頭寫進暫存檔再交給 curl，key 不會出現在 process list。
api() {
  local method="$1" url="$2" headers="$3" body="${4:-}" out hdr
  out=$(mktemp); hdr=$(mktemp)
  printf '%s\nContent-Type: application/json\n' "$headers" > "$hdr"
  local args=(-sS -o "$out" -w '%{http_code}' -X "$method" -H "@$hdr")
  [[ -n "$body" ]] && args+=(--data "$body")
  HTTP_STATUS=$(curl "${args[@]}" "$url") || HTTP_STATUS=000
  RESPONSE=$(cat "$out"); rm -f "$out" "$hdr"
}
api_ok() { [[ "$HTTP_STATUS" =~ ^2 ]]; }

paddle_api() { api "$1" "$PADDLE_API_BASE_URL$2" "Authorization: Bearer $PADDLE_API_KEY" "${3:-}"; }
paddle_fail() {
  warn "Paddle API $1 失敗（HTTP $HTTP_STATUS）：$(json_get 'error.code') $(json_get 'error.detail')"
  exit 1
}

# missing_permissions：GET / 的回應（RESPONSE）裡，PADDLE_PERMISSIONS 有哪些這把 key 沒有，以空白分隔。
# Paddle 的 API root 會列出 key 的所有權限（write 隱含的 read 也列），不會改到任何資料。
missing_permissions() {
  local granted=",$(json_get 'data.caller.permissions')," p missing=()
  for p in "${PADDLE_PERMISSIONS[@]}"; do [[ "$granted" == *",$p,"* ]] || missing+=("$p"); done
  printf '%s' "${missing[*]}"
}

# worker_secret_exists NAME：Cloudflare 上的 Worker 已經有這個 secret。
worker_secret_exists() {
  local list; list=$(wrangler secret list -c "$WORKER_CONFIG" --format json 2>/dev/null) || return 1
  printf '%s' "$list" | node -e '
    let s = ""; process.stdin.on("data", d => s += d).on("end", () => {
      try { process.exit(JSON.parse(s).some(x => x.name === process.argv[1]) ? 0 : 1); } catch { process.exit(1); }
    });' "$1"
}

# put_worker_secret NAME VALUE：經由 stdin 交給 wrangler，值不會出現在指令參數與畫面上。
put_worker_secret() {
  if printf '%s' "$2" | wrangler secret put "$1" -c "$WORKER_CONFIG" >/dev/null 2>&1; then
    CF_SECRETS+=("$1")
    printf '  %s✓ set%s Worker secret %s\n' "$GREEN" "$RESET" "$1"
  else
    warn "wrangler secret put $1 失敗；確認 wrangler 登入的帳號，再重跑"
    exit 1
  fi
}

# need_secret NAME：還沒設定、或已設定但要換新的，就回傳成功。
need_secret() {
  worker_secret_exists "$1" || return 0
  note "Cloudflare 上已經有 $1。"
  confirm "要換成新的嗎？"
}

# wait_for URL：重試一分鐘，直到 URL 回 2xx（custom domain 第一次部署時，憑證要一點時間）。
wait_for() {
  local i
  for i in $(seq 1 12); do
    curl -fsS -o /dev/null "$1" 2>/dev/null && return 0
    sleep 5
  done
  return 1
}

run_wizard() {

TOTAL_STAGES=16

cd "$(git rev-parse --show-toplevel)"
for tool in curl node gh; do
  command -v "$tool" >/dev/null 2>&1 || { warn "需要 $tool，請先安裝"; exit 1; }
done
[[ -x node_modules/.bin/wrangler ]] || { warn "repo 裡還沒裝套件，先跑 npm ci"; exit 1; }

banner "Naruhodo production 開通（#97）"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "登入 wrangler 與 gh"
say "wizard 用本機登入的 wrangler 建 D1、部署、設定 Worker secrets，用 gh 設定 GitHub 的 secret 與 variables。"
if ! wrangler whoami --json >/dev/null 2>&1; then
  step "瀏覽器會打開 Cloudflare 的授權頁：用擁有 $DOMAIN 的帳號登入並允許。"
  wrangler login
fi
if ! gh auth status >/dev/null 2>&1; then
  step "gh 還沒登入，接著執行 gh auth login。"
  gh auth login
fi
note "GitHub repo：$(gh repo view --json nameWithOwner -q .nameWithOwner)"
pause

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Workers Paid 方案"
say "Workers Free 每次請求只有 10 ms CPU、每天 10 萬次請求，撐不住付費產品"
say "（docs/research/track-b-backend-facts.md）。Workers Paid 每個帳號每月最低 US\$5。"
open_url "https://dash.cloudflare.com/?to=/:account/workers/plans"
step "在 Workers plans 頁確認目前是 Paid；不是的話升級到 Workers Paid。"
pause "確認是 Workers Paid 後按 Enter"

# ── 3 ────────────────────────────────────────────────────────────────────
stage "GitHub Actions 用的 Cloudflare API token"
say "CI 用這個 token 部署網站與 Worker、套用 D1 migrations。權限只開需要的，外洩也碰不到 DNS 或其他服務。"
CLOUDFLARE_ACCOUNT_ID=$(_existing CLOUDFLARE_ACCOUNT_ID || true)
if [[ -z "$CLOUDFLARE_ACCOUNT_ID" ]]; then
  CLOUDFLARE_ACCOUNT_ID=$(wrangler whoami 2>&1 | grep -oE '\b[0-9a-f]{32}\b' | head -n 1 || true)
  if [[ -n "$CLOUDFLARE_ACCOUNT_ID" ]]; then
    note "wrangler whoami 讀到的 Account ID：$CLOUDFLARE_ACCOUNT_ID"
    confirm "是擁有 $DOMAIN 的那個帳號嗎？" || CLOUDFLARE_ACCOUNT_ID=""
  fi
fi
if [[ -z "$CLOUDFLARE_ACCOUNT_ID" ]]; then
  step "Cloudflare 後台按 Ctrl+K，搜尋「Copy account ID」並選擇（或 Workers & Pages → Account Details）。"
  ask CLOUDFLARE_ACCOUNT_ID "貼上 Account ID："
fi
write_env CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"
set_var CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"
if gh secret list 2>/dev/null | grep -q '^CLOUDFLARE_API_TOKEN\b' && ! confirm "GitHub 已經有 CLOUDFLARE_API_TOKEN，要換一把新的嗎？"; then
  note "沿用 GitHub 上現有的 token。"
else
  open_url "https://dash.cloudflare.com/?to=/:account/api-tokens"
  step "Account API tokens → Create Token；Token name 填 naruhodo-github-actions。"
  step "Permission policies 點「Edit Cloudflare Workers」範本，會帶出兩條 policy："
  note "    「All zones … Workers Routes Write」：按鉛筆，範圍改成 Specified Domains → $DOMAIN。"
  note "    「Entire … Account」：按鉛筆，搜尋 D1 並選 Edit（範本沒有 D1，套用 migrations 要用）。"
  note "    同一條裡的 Workers KV Storage、Workers R2 Storage 用不到，可以取消。"
  step "Token expiration 選 1 year；Client IP address filtering 留空（GitHub Actions 的 IP 每次不同）。"
  step "Review token：確認有 Workers Scripts Write、Account Settings Read、D1 Write、Workers Routes Write（$DOMAIN）。"
  step "Create token，複製 token（只會顯示一次）。"
  while :; do
    ask_secret CLOUDFLARE_API_TOKEN "貼上 token（輸入不會顯示）："
    api GET "https://api.cloudflare.com/client/v4/accounts/$CLOUDFLARE_ACCOUNT_ID/tokens/verify" "Authorization: Bearer $CLOUDFLARE_API_TOKEN"
    [[ "$(json_get 'result.status')" == active ]] && break
    warn "Cloudflare 驗證不過（HTTP $HTTP_STATUS）：確認是 Account API token、而且複製完整"
  done
  set_secret CLOUDFLARE_API_TOKEN "$CLOUDFLARE_API_TOKEN"
  unset CLOUDFLARE_API_TOKEN
fi
pause

# ── 4 ────────────────────────────────────────────────────────────────────
stage "正式的 D1 資料庫（自動）"
say "建立 D1 資料庫 $D1_NAME（位置：亞太），把 database_id 寫進 $WORKER_CONFIG，再套用 migrations。"
D1_DATABASE_ID=$(d1_id)
if [[ -n "$D1_DATABASE_ID" ]]; then
  note "已經有 $D1_NAME：$D1_DATABASE_ID，略過建立。"
elif confirm "要建立 D1 資料庫 $D1_NAME 嗎？"; then
  wrangler d1 create "$D1_NAME" --location apac >/dev/null
  D1_DATABASE_ID=$(d1_id)
  [[ -n "$D1_DATABASE_ID" ]] || { warn "建立後找不到 $D1_NAME，請看上面的錯誤"; exit 1; }
else
  warn "沒有 D1 就不能部署 Worker；之後重跑這個 wizard。"; exit 1
fi
write_env D1_DATABASE_ID "$D1_DATABASE_ID"
# 只換最上層（production）那一個：它在檔案裡最先出現；env.dev／env.test 的本機 D1 維持 "local"
node -e '
  const fs = require("fs"); const [file, id] = process.argv.slice(1);
  const text = fs.readFileSync(file, "utf8");
  if (!text.includes(`"database_id": "${id}"`)) fs.writeFileSync(file, text.replace(`"database_id": "local"`, `"database_id": "${id}"`));
' "$WORKER_CONFIG" "$D1_DATABASE_ID"
printf '  %s✓ wrote%s database_id → %s\n' "$GREEN" "$RESET" "$WORKER_CONFIG"
note "這是 repo 裡的檔案：最後一步會請你把這個改動開 PR 合併。"
step "接著套用 migrations：wrangler 會列出要套用的檔案，請你確認。"
wrangler d1 migrations apply "$D1_NAME" --remote -c "$WORKER_CONFIG"
pause

# ── 5 ────────────────────────────────────────────────────────────────────
stage "第一次部署 Worker 與網站（自動）"
say "從這台電腦部署一次：Worker 要先存在，接下來才能設定 secrets。"
say "部署時 Cloudflare 會自動建 api.$DOMAIN 與 $DOMAIN 的 DNS 記錄和 HTTPS 憑證。"
say "網站這次還沒有 Paddle 的 client-side token，checkout 頁要等開通自動部署後的下一次部署才會正常。"
if curl -fsS -o /dev/null "$API_ORIGIN/v1/health" 2>/dev/null && curl -fsS -o /dev/null "$SITE_ORIGIN/zh-tw/" 2>/dev/null \
  && ! confirm "Worker 與網站都已經上線了，要重新部署嗎？"; then
  note "略過部署。"
else
  confirm "要部署嗎？" || { warn "沒有部署就不能設定 secrets；之後重跑。"; exit 1; }
  wrangler deploy -c "$WORKER_CONFIG"
  npm run site:build
  wrangler deploy -c "$SITE_CONFIG"
fi
say "等 $API_ORIGIN/v1/health 與 $SITE_ORIGIN 回應（最多各一分鐘）…"
if wait_for "$API_ORIGIN/v1/health"; then
  note "✓ Worker 健康檢查通過（D1 連得上）"
else
  warn "Worker 還沒有回應"
  SKIPPED+=("$API_ORIGIN/v1/health 沒有回應：看 Cloudflare 後台 naruhodo-api 的 Custom Domains 與 log")
fi
if wait_for "$SITE_ORIGIN/zh-tw/"; then
  note "✓ 網站上線"
else
  warn "網站還沒有回應"
  SKIPPED+=("$SITE_ORIGIN 沒有回應：看 Cloudflare 後台 naruhodo-site 的 Custom Domains")
fi
pause

# ── 6 ────────────────────────────────────────────────────────────────────
stage "Anthropic API key（CLAUDE_API_KEY）"
say "開一個專用的 workspace 並設定每月花費上限：成本只算 Hosted Translation，量真實成本時直接看這個 workspace。"
if need_secret CLAUDE_API_KEY; then
  open_url "https://platform.claude.com/settings/workspaces"
  step "Create workspace → 名稱 naruhodo-production → Create workspace（要 org admin）。"
  step "選這個 workspace → Spend limits → Monthly limit 的 Change limit，設定你願意承擔的上限。"
  step "到 API keys 頁 → Create key：名稱 naruhodo-worker，範圍選 naruhodo-production。"
  step "到期時間選最長的（預設 30 天）：key 過期那天起，所有 Hosted Translation 都會失敗。建立後複製。"
  while :; do
    ask_secret CLAUDE_API_KEY "貼上 API key（輸入不會顯示）："
    api GET "https://api.anthropic.com/v1/models?limit=1" "x-api-key: $CLAUDE_API_KEY
anthropic-version: 2023-06-01"
    api_ok && break
    warn "Anthropic 拒絕這把 key（HTTP $HTTP_STATUS $(json_get 'error.type')），請重貼"
  done
  put_worker_secret CLAUDE_API_KEY "$CLAUDE_API_KEY"
  unset CLAUDE_API_KEY
fi
pause

# ── 7 ────────────────────────────────────────────────────────────────────
stage "Resend 寄件網域 $MAIL_DOMAIN"
say "驗證碼信從 noreply@$MAIL_DOMAIN 寄出（$WORKER_CONFIG 的 MAIL_FROM）。"
say "Resend 建議用子網域寄信，寄信的信譽跟主網域分開。"
open_url "https://resend.com/domains"
step "Domains → Add Domain → 輸入 $MAIL_DOMAIN，region 選 ap-northeast-1（東京）。"
step "在 Domains 頁按「Sign in to Cloudflare」：授權後 Resend 會自動把 DNS 記錄加到 $DOMAIN。"
note "    不想授權的話，照 Records 分頁逐筆加到 Cloudflare 的 DNS；CNAME 要設成 DNS only（灰色雲）。"
step "等 domain 狀態變成 Verified（通常 15 分鐘內，最長 72 小時）。"
if ! confirm "已經是 Verified 了嗎？"; then
  say "驗證完成後重跑這個 wizard，前面的步驟會略過。"; exit 0
fi
pause

# ── 8 ────────────────────────────────────────────────────────────────────
stage "Resend API key（RESEND_API_KEY）"
if need_secret RESEND_API_KEY; then
  open_url "https://resend.com/api-keys"
  step "Create API Key → 名稱 naruhodo-worker → Permission 選 Sending access → Domain 選 $MAIL_DOMAIN → 建立並複製。"
  note "只能寄信、只能用這個網域：外洩了也不能讀信或改設定。"
  while :; do
    ask_secret RESEND_API_KEY "貼上 API key（輸入不會顯示）："
    [[ "$RESEND_API_KEY" == re_* ]] && break
    warn "Resend 的 key 開頭是 re_，請重貼"
  done
  put_worker_secret RESEND_API_KEY "$RESEND_API_KEY"
  unset RESEND_API_KEY
fi
note "第 15 步會實際寄一封驗證碼信給你，確認這把 key 能用。"
pause

# ── 9 ────────────────────────────────────────────────────────────────────
stage "Paddle live 帳號與網站審核"
say "live 帳號跟 sandbox 完全分開：產品、價格、key、webhook 都要重建。"
say "live 的 checkout 只能開在審核通過的網域上，所以要先送 $DOMAIN 審核。"
open_url "$PADDLE_DASHBOARD/signup"
step "還沒有 live 帳號就註冊（已經有就直接登入）。"
step "Settings → Website approval，送出 $DOMAIN。"
note "Paddle 會看網站上有沒有：產品說明、價格、功能；導覽列連得到 Terms、Refund Policy、Privacy Policy；"
note "Terms 裡有品牌名稱；首頁找得到聯絡 email；HTTPS。多數自動核准，人工審核大約 5–7 個工作天。"
if ! confirm "$DOMAIN 已經審核通過了嗎？"; then
  say "審核通過後重跑這個 wizard。"; exit 0
fi
pause

# ── 10 ───────────────────────────────────────────────────────────────────
stage "Paddle live 的 API key"
say "這把 key 只留在記憶體：接下來用它建立 price 與 webhook，最後存成 Worker 的 PADDLE_API_KEY。"
PADDLE_API_KEY=""
PADDLE_PRICE_ID=$(_existing PADDLE_PRICE_ID || true)
PADDLE_NOTIFICATION_SETTING_ID=$(_existing PADDLE_NOTIFICATION_SETTING_ID || true)
if [[ -n "$PADDLE_PRICE_ID" && -n "$PADDLE_NOTIFICATION_SETTING_ID" ]] && worker_secret_exists PADDLE_API_KEY \
  && ! confirm "Paddle 已經設定過，要換一把新的 API key 嗎？"; then
  note "沿用 Cloudflare 上現有的 PADDLE_API_KEY。"
else
  open_url "$PADDLE_DASHBOARD/settings/authentication"
  step "API keys 分頁 → New API key → Name：naruhodo-worker。"
  step "Permissions 勾這幾個（write 都包含 read）："
  note "    transaction.write、product.write、price.write、customer.write、"
  note "    subscription.write、notification_setting.write、notification.read、"
  note "    customer_portal_session.write（畫面上是 Customer portal sessions → Write；"
  note "    旁邊的 Customer authentication tokens 不用勾）"
  step "Expiry date 設最長；Save 後複製 key（只會顯示一次，開頭是 pdl_live_apikey_）。"
  while :; do
    ask_secret PADDLE_API_KEY "貼上 API key（輸入不會顯示）："
    if [[ "$PADDLE_API_KEY" != pdl_live_apikey_* ]]; then
      warn "開頭不是 pdl_live_apikey_，可能貼到 sandbox 的 key 或 client-side token"; continue
    fi
    paddle_api GET /
    if ! api_ok || [[ -z "$(json_get 'data.caller.account')" ]]; then
      warn "Paddle 拒絕這把 key（HTTP $HTTP_STATUS $(json_get 'error.code')），請檢查後重貼"; continue
    fi
    missing=$(missing_permissions)
    [[ -z "$missing" ]] && break
    warn "這把 key 少了權限：$missing。回 Paddle 編輯這把 key 補勾後 Save，再貼一次"
  done
  note "key 到期就失效：到期前回這個頁面建新的，再重跑這個 wizard。"
fi
pause

# ── 11 ───────────────────────────────────────────────────────────────────
stage "Paddle 的 client-side token"
say "checkout 頁的 Paddle.js 用它初始化。它會出現在網頁原始碼裡，不是秘密，"
say "放在 GitHub variables，CI build 網站時帶進去（PUBLIC_PADDLE_CLIENT_TOKEN）。"
PADDLE_CLIENT_TOKEN=$(_existing PADDLE_CLIENT_TOKEN || true)
if [[ -z "$PADDLE_CLIENT_TOKEN" ]] || confirm "已經設定過 client-side token，要換嗎？"; then
  open_url "$PADDLE_DASHBOARD/settings/authentication"
  step "Client-side tokens 分頁 → New client-side token → Name：naruhodo-site → Save → Copy（開頭是 live_）。"
  while :; do
    ask PADDLE_CLIENT_TOKEN "貼上 client-side token："
    [[ "$PADDLE_CLIENT_TOKEN" == live_* ]] && break
    warn "live 的 client-side token 開頭是 live_，請再貼一次"
  done
fi
write_env PADDLE_CLIENT_TOKEN "$PADDLE_CLIENT_TOKEN"
set_var PADDLE_CLIENT_TOKEN "$PADDLE_CLIENT_TOKEN"
pause

# ── 12 ───────────────────────────────────────────────────────────────────
stage "default payment link"
say "Paddle 規定：沒設 default payment link 就不能建立 transaction，而且 live 只能填審核通過的網域。"
say "Worker 自己組 checkout 網址（$SITE_ORIGIN/<語言>/checkout?_ptxn=…），這個值只要合法就好。"
open_url "$PADDLE_DASHBOARD"
step "Checkout → Checkout settings → Default payment link 填 $SITE_ORIGIN/zh-tw/checkout → Save。"
pause "確認有值後按 Enter"

# ── 13 ───────────────────────────────────────────────────────────────────
stage "產品與年繳 price（自動）"
say "建立產品「Naruhodo Hosted Translation」與 USD 20／年的 price（草案價格，上線後可以再調）。"
say "之後改價格：新增一個 price，再更新 Worker 的 PADDLE_PRICE_ID；不要改已經有人訂閱的 price。"
if [[ -n "$PADDLE_PRICE_ID" ]]; then
  note "已經建立過：$(_existing PADDLE_PRODUCT_ID || true) / $PADDLE_PRICE_ID，略過。"
elif [[ -z "$PADDLE_API_KEY" ]]; then
  warn "這次沒有輸入 Paddle API key，無法建立；重跑並在第 10 步換 key。"; exit 1
elif confirm "要建立產品與 price 嗎？"; then
  paddle_api POST /products '{"name":"Naruhodo Hosted Translation","tax_category":"standard","description":"Hosted translation for the Naruhodo Chrome extension (annual subscription)."}'
  api_ok || paddle_fail "create product"
  write_env PADDLE_PRODUCT_ID "$(json_get 'data.id')"
  paddle_api POST /prices "{\"product_id\":\"$PADDLE_PRODUCT_ID\",\"description\":\"Annual\",\"name\":\"Annual\",\"unit_price\":{\"amount\":\"2000\",\"currency_code\":\"USD\"},\"billing_cycle\":{\"interval\":\"year\",\"frequency\":1}}"
  api_ok || paddle_fail "create price"
  write_env PADDLE_PRICE_ID "$(json_get 'data.id')"
else
  warn "沒有 price 就不能訂閱；之後重跑。"; exit 1
fi
if need_secret PADDLE_PRICE_ID; then put_worker_secret PADDLE_PRICE_ID "$PADDLE_PRICE_ID"; fi
pause

# ── 14 ───────────────────────────────────────────────────────────────────
stage "webhook destination 與 secret（自動）"
say "建立 notification destination $API_ORIGIN/webhooks/paddle，訂閱訂閱相關事件與 adjustment.updated"
say "（全額退款時 Worker 立即取消訂閱，#97）。Paddle 回傳的簽章 secret 直接存成 PADDLE_WEBHOOK_SECRET，不顯示。"
if [[ -n "$PADDLE_NOTIFICATION_SETTING_ID" ]]; then
  note "已經建立過：$PADDLE_NOTIFICATION_SETTING_ID，略過。"
  worker_secret_exists PADDLE_WEBHOOK_SECRET \
    || SKIPPED+=("PADDLE_WEBHOOK_SECRET 不在 Cloudflare：到 Paddle 後台刪掉這個 notification destination，清掉 $ENV_FILE 的 PADDLE_NOTIFICATION_SETTING_ID 後重跑")
elif [[ -z "$PADDLE_API_KEY" ]]; then
  warn "這次沒有輸入 Paddle API key，無法建立；重跑並在第 10 步換 key。"; exit 1
elif confirm "要建立 webhook destination 嗎？"; then
  paddle_api POST /notification-settings "{\"description\":\"naruhodo production\",\"type\":\"url\",\"destination\":\"$API_ORIGIN/webhooks/paddle\",\"subscribed_events\":$WEBHOOK_EVENTS,\"traffic_source\":\"all\"}"
  api_ok || paddle_fail "create notification setting"
  put_worker_secret PADDLE_WEBHOOK_SECRET "$(json_get 'data.endpoint_secret_key')"
  write_env PADDLE_NOTIFICATION_SETTING_ID "$(json_get 'data.id')"
else
  warn "沒有 webhook，Worker 就不知道誰訂閱了；之後重跑。"; exit 1
fi
if [[ -n "$PADDLE_API_KEY" ]]; then
  put_worker_secret PADDLE_API_KEY "$PADDLE_API_KEY"
  PADDLE_API_KEY=""
fi
pause

# ── 15 ───────────────────────────────────────────────────────────────────
stage "驗證"
say "1. 不帶簽章送一個請求給 webhook：Worker 要回 401（路徑在，而且會驗簽章）。"
api POST "$API_ORIGIN/webhooks/paddle" "X-Wizard: check" '{}'
if [[ "$HTTP_STATUS" == 401 ]]; then
  note "✓ webhook 回 401"
else
  warn "webhook 回 HTTP $HTTP_STATUS，預期 401"
  SKIPPED+=("webhook 沒有回 401：看 naruhodo-api 的 log")
fi
say "2. 寄一封登入驗證碼給你，確認 Resend 與 MAIL_FROM 都對。"
ask CHECK_EMAIL "收信的 email："
api POST "$API_ORIGIN/v1/auth/send-code" "X-Wizard: check" "{\"email\":\"$CHECK_EMAIL\"}"
if [[ "$HTTP_STATUS" == 204 ]]; then
  confirm "收到來自 noreply@$MAIL_DOMAIN 的驗證碼信了嗎？（可能在垃圾信件匣）" \
    || SKIPPED+=("驗證碼信沒收到：看 Resend 後台的 Emails 紀錄與 naruhodo-api 的 log")
else
  warn "寄送失敗（HTTP $HTTP_STATUS）：$(json_get 'error')"
  SKIPPED+=("驗證碼寄送失敗：看 naruhodo-api 的 log（多半是 RESEND_API_KEY，或寄件網域還沒驗證）")
fi
note "付款流程要真的買一次才驗得到，見最後的提示。"
pause

# ── 16 ───────────────────────────────────────────────────────────────────
stage "打開自動部署"
say "打開 DEPLOY_ENABLED 之後，合併到 main 的 PR 只要 CI 通過，就會自動部署網站與 Worker（ADR 0008）。"
if git diff --quiet -- "$WORKER_CONFIG"; then
  note "$WORKER_CONFIG 沒有待 commit 的改動。"
else
  warn "$WORKER_CONFIG 的 database_id 還沒 commit：開 PR 合併後會觸發第一次自動部署，網站也會帶上 client-side token。"
fi
if confirm "要打開自動部署嗎？"; then
  set_var DEPLOY_ENABLED true
else
  SKIPPED+=("自動部署還沒打開：gh variable set DEPLOY_ENABLED --body true")
fi

finish
(( ${#CF_SECRETS[@]} )) && note "設定了 ${#CF_SECRETS[@]} 個 Worker secret：${CF_SECRETS[*]}"
say "非秘密的 ID：$ENV_FILE"
say "接下來："
say "  • 把 $WORKER_CONFIG 的 database_id 開 PR 合併，觸發第一次自動部署。"
say "  • 用 100% 折扣碼在 $SITE_ORIGIN 實際訂閱一次，確認外掛顯示本月額度（Paddle 的 go-live checklist 也這樣測）。"
say "  • 上線日把 PRIVACY.md、TERMS.md、REFUND.md 的生效日期改掉，再用 release.yml 發一版外掛。"
}

run_wizard "$@"; exit
